contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        require(true);

        bool setMinSumReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setMinSumReverted = true; } else { setMinSumReverted = false; }

        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initializedReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initializedReverted = true; } else { initializedReverted = false; }

        assert(!setMinSumReverted && minSumAfter == _val && !initializedReverted);
    }

    receive() external payable {}
}

